package app.metrolife;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.net.URI;
import java.util.List;
import javax.imageio.ImageIO;

/** In-game leases, generated art and rent. No remote artwork or real payments. */
final class Property {
    final GameService g;static final int CELL=24,PRICE=35,DAYS=7,BOARD_PRICE=300,BOARD_DAYS=3;
    Property(GameService g){this.g=g;}
    ObjectNode state(ObjectNode w,String city){ObjectNode p=g.store.data.withObject("property").withObject(w.path("id").asText()).withObject(city);if(!p.has("plots")){p.putArray("plots");p.putArray("billboards");p.put("revision",0);}return p;}
    void expire(ObjectNode p){for(String key:List.of("plots","billboards")){ArrayNode rows=p.withArray(key);for(int i=rows.size()-1;i>=0;i--)if(rows.get(i).path("endsAt").asLong()<=g.now()){rows.remove(i);p.put("revision",p.path("revision").asInt()+1);}}}
    void syncPlots(ObjectNode s,ObjectNode w){int count=0;for(JsonNode city:g.content.world.path("cities")){ObjectNode p=state(w,city.path("id").asText());expire(p);for(JsonNode row:p.path("plots"))if(row.path("userId").asText().equals(s.path("userId").asText()))count++;}s.withObject("_externalMetrics").put("plots",count);}
    boolean overlap(JsonNode a,JsonNode b){return a.path("x").asInt()<b.path("x").asInt()+b.path("w").asInt()&&a.path("x").asInt()+a.path("w").asInt()>b.path("x").asInt()&&a.path("y").asInt()<b.path("y").asInt()+b.path("h").asInt()&&a.path("y").asInt()+a.path("h").asInt()>b.path("y").asInt();}
    String link(JsonNode body){String link=body.path("link").asText().trim();if(link.isEmpty())return "";try{URI uri=URI.create(link);GameService.require(link.length()<=2048&&List.of("https","http").contains(uri.getScheme())&&uri.getHost()!=null&&uri.getUserInfo()==null,400,"Use a full http or https link, or leave it blank");}catch(IllegalArgumentException e){throw new ApiException(400,"Use a full http or https link, or leave it blank");}return link;}
    ObjectNode publicAd(JsonNode row,String kind){ObjectNode out=((ObjectNode)row).deepCopy();out.remove(List.of("userId","slot","startsAt"));out.put("image","/api/"+kind+"/"+row.path("id").asText()+"/image");return out;}
    ObjectNode readPlots(String token,String city){JsonNode cfg=g.content.city(city).path("plots");ObjectNode w=g.world(g.session(token,false)),p=state(w,city);expire(p);ObjectNode out=g.object().put("city",city).put("price",PRICE).put("days",DAYS).put("cols",cfg.path("cols").asInt()).put("rows",cfg.path("rows").asInt()).put("atlasCell",CELL).put("atlas","/api/plots/atlas.png?city="+city+"&world="+w.path("id").asText()+"&v="+p.path("revision").asInt());ArrayNode ads=out.putArray("ads");for(JsonNode row:p.path("plots"))ads.add(publicAd(row,"plots"));out.putArray("holds");g.store.save();return out;}
    ObjectNode buyPlot(String token,JsonNode body){String city=body.path("city").asText();ObjectNode s=g.civic.resident(token,city),w=g.world(g.session(token,true)),p=state(w,city);expire(p);JsonNode cfg=g.content.city(city).path("plots");
        for(String key:List.of("x","y","w","h"))GameService.require(body.path(key).isIntegralNumber()&&body.path(key).canConvertToInt(),400,"Choose whole grid cells");int x=body.path("x").asInt(),y=body.path("y").asInt(),width=body.path("w").asInt(),height=body.path("h").asInt();GameService.require(width>=1&&height>=1&&width<=12&&height<=12&&x>=0&&y>=0&&x<=cfg.path("cols").asInt()-width&&y<=cfg.path("rows").asInt()-height,400,"Choose a rectangle inside the plot grid, up to 12 by 12");for(JsonNode row:p.path("plots"))GameService.require(!overlap(body,row),409,"These cells have just been booked. Choose another spot");String title=g.civic.text(body,"title",3,48),link=link(body);int cost=width*height*PRICE;GameService.require(s.path("cash").asDouble()>=cost,402,"You need $"+cost+" for these cells");
        ObjectNode row=p.withArray("plots").addObject().put("id",g.id()).put("x",x).put("y",y).put("w",width).put("h",height).put("title",title).put("link",link).put("owner",s.path("username").asText()).put("userId",s.path("userId").asText()).put("endsAt",g.now()+DAYS*1440000L);pay(s,cost);g.civic.external(s,"plots");syncPlots(s,w);g.finishProgress(s);p.put("revision",p.path("revision").asInt()+1);g.store.save();ObjectNode out=g.object();out.set("ad",publicAd(row,"plots"));out.set("sim",g.publicSim(s));return out;
    }
    ObjectNode readBoards(String token,String city){int slots=g.content.city(city).path("billboardSlots").asInt();ObjectNode p=state(g.world(g.session(token,false)),city);expire(p);ObjectNode out=g.object().put("city",city).put("price",BOARD_PRICE).put("days",BOARD_DAYS);ArrayNode rows=out.putArray("slots");for(int slot=1;slot<=slots;slot++){ObjectNode item=rows.addObject().put("slot",slot).putNull("ad");long free=g.now();int queue=0;for(JsonNode row:p.path("billboards"))if(row.path("slot").asInt()==slot){free=Math.max(free,row.path("endsAt").asLong());if(row.path("startsAt").asLong()<=g.now())item.set("ad",publicAd(row,"billboards"));else queue++;}item.put("queue",queue).put("freeFrom",free);}g.store.save();return out;}
    ObjectNode book(String token,JsonNode body){String city=body.path("city").asText();ObjectNode s=g.civic.resident(token,city),w=g.world(g.session(token,true)),p=state(w,city);expire(p);int slot=body.path("slot").asInt();GameService.require(body.path("slot").isIntegralNumber()&&body.path("slot").canConvertToInt()&&slot>=1&&slot<=g.content.city(city).path("billboardSlots").asInt(),400,"Choose a listed billboard");String title=g.civic.text(body,"title",3,48),link=link(body);long start=g.now();int count=0;for(JsonNode row:p.path("billboards"))if(row.path("slot").asInt()==slot){GameService.require(!row.path("userId").asText().equals(s.path("userId").asText()),409,"You already have a booking on this board");start=Math.max(start,row.path("endsAt").asLong());count++;}GameService.require(count<4,409,"This board's booking list is full");GameService.require(s.path("cash").asDouble()>=BOARD_PRICE,402,"You need $"+BOARD_PRICE+" to book a billboard");
        ObjectNode row=p.withArray("billboards").addObject().put("id",g.id()).put("slot",slot).put("title",title).put("link",link).put("owner",s.path("username").asText()).put("userId",s.path("userId").asText()).put("startsAt",start).put("endsAt",start+BOARD_DAYS*1440000L);pay(s,BOARD_PRICE);g.civic.external(s,"billboards");g.finishProgress(s);g.store.save();ObjectNode out=g.object();ObjectNode ad=publicAd(row,"billboards");ad.put("startsAt",start);out.set("ad",ad);out.set("sim",g.publicSim(s));return out;
    }
    void pay(ObjectNode s,double cost){s.put("cash",s.path("cash").asDouble()-cost);ObjectNode ledger=s.withObject("moneyToday");ledger.put("spent",ledger.path("spent").asDouble()+cost);}
    void rent(ObjectNode s,ObjectNode w,int elapsed){if(elapsed>0){double rate=s.path("home").path("rent").asDouble();if(g.civic.policy(w,s.path("home").path("city").asText()).equals("housing"))rate=Math.floor(rate*.8);s.put("rentDebt",s.path("rentDebt").asDouble()+rate*elapsed);}double payment=Math.min(s.path("rentDebt").asDouble(),Math.max(0,s.path("cash").asDouble()-s.path("_pendingAction").path("cost").asDouble()));if(payment>0){pay(s,payment);s.put("rentDebt",s.path("rentDebt").asDouble()-payment);}}
    ObjectNode move(String token,JsonNode body){String city=body.path("city").asText(),nh=body.path("neighborhood").asText();ObjectNode target=g.content.neighborhood(city,nh),s=g.civic.resident(token,city);GameService.require(!s.path("home").path("city").asText().equals(city)||!s.path("home").path("neighborhood").asText().equals(nh),409,"You already live here");GameService.require(s.path("rentDebt").asDouble()==0,402,"Clear your rent balance before moving");int deposit=target.path("rent").asInt();GameService.require(s.path("cash").asDouble()>=deposit,402,"Moving costs one day's rent: $"+deposit);pay(s,deposit);s.putObject("home").put("city",city).put("neighborhood",nh).put("rent",deposit);s.put("loc","home");g.store.save();ObjectNode out=g.object();out.set("sim",g.publicSim(s));return out;}
    ObjectNode homes(String token,String city){g.content.city(city);String wid=g.world(g.session(token,false)).path("id").asText();ObjectNode out=g.object();ArrayNode homes=out.putArray("homes");ArrayNode residents=g.mapper.createArrayNode();g.table("sims").forEach(residents::add);g.community.residents().path(wid).forEach(residents::add);for(JsonNode s:residents)if(s.path("worldId").asText().equals(wid)&&s.path("home").path("city").asText().equals(city)){ObjectNode row=homes.addObject().put("id",s.path("userId").asText()+"-home").put("userId",s.path("userId").asText()).put("username",s.path("username").asText()).put("city",city).put("neighborhood",s.path("home").path("neighborhood").asText()).put("npc",s.path("npc").asBoolean());row.set("look",s.path("look").deepCopy());}return out.put("total",homes.size());}
    byte[] atlas(String token,String city,String world){JsonNode cfg=g.content.city(city).path("plots");ObjectNode w=g.world(g.session(token,false));GameService.require(world.isEmpty()||world.equals(w.path("id").asText()),403,"This atlas belongs to another world");ObjectNode p=state(w,city);expire(p);int width=cfg.path("cols").asInt()*CELL,height=cfg.path("rows").asInt()*CELL;BufferedImage image=new BufferedImage(width,height,BufferedImage.TYPE_INT_RGB);Graphics2D canvas=image.createGraphics();canvas.setColor(new Color(0xd7cbb4));canvas.fillRect(0,0,width,height);canvas.setColor(new Color(0xa69b85));for(int x=0;x<=width;x+=CELL)canvas.drawLine(x,0,x,height);for(int y=0;y<=height;y+=CELL)canvas.drawLine(0,y,width,y);for(JsonNode row:p.path("plots")){int x=row.path("x").asInt()*CELL,y=row.path("y").asInt()*CELL,rw=row.path("w").asInt()*CELL,rh=row.path("h").asInt()*CELL;canvas.setColor(color(row.path("id").asText()));canvas.fillRoundRect(x+1,y+1,rw-2,rh-2,6,6);canvas.setColor(new Color(0xfff4d9));canvas.fillRect(x+3,y+3,Math.max(1,rw-6),Math.max(2,rh/5));canvas.setColor(Color.WHITE);canvas.setFont(new Font("SansSerif",Font.BOLD,Math.min(16,rh-6)));canvas.setClip(x+2,y+2,rw-4,rh-4);canvas.drawString(row.path("title").asText(),x+4,y+Math.min(rh-4,18));canvas.setClip(null);}canvas.dispose();return png(image);}
    Color color(String id){return Color.getHSBColor((id.hashCode()&0xffff)/65535f,.55f,.55f);}
    byte[] art(String token,String kind,String id){ObjectNode w=g.world(g.session(token,false));JsonNode found=null;for(JsonNode city:g.content.world.path("cities")){ObjectNode p=state(w,city.path("id").asText());expire(p);for(JsonNode row:p.path(kind))if(row.path("id").asText().equals(id))found=row;}GameService.require(found!=null,404,"This booking has ended or is in another world");BufferedImage image=new BufferedImage(512,288,BufferedImage.TYPE_INT_RGB);Graphics2D c=image.createGraphics();c.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);c.setColor(color(id));c.fillRect(0,0,512,288);c.setColor(new Color(255,247,234));c.fillRoundRect(24,24,464,240,24,24);c.setColor(color(id));c.setFont(new Font("SansSerif",Font.BOLD,28));String title=found.path("title").asText();int y=95;while(!title.isEmpty()&&y<210){int end=Math.min(24,title.length());c.drawString(title.substring(0,end),44,y);title=title.substring(end);y+=36;}c.setFont(new Font("SansSerif",Font.PLAIN,18));c.drawString("By "+found.path("owner").asText(),44,236);c.dispose();return png(image);}
    byte[] png(BufferedImage image){try{ByteArrayOutputStream out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);return out.toByteArray();}catch(Exception e){throw new IllegalStateException("Could not draw local art",e);}}
}
